/* Control, plan, impact and verification presentation. Mutation stays in workspace.js. */
(() => { 'use strict';window.GpoControlView=Object.freeze({create({state,esc,say,tr,riskFor,badges,topDomainForRule,sectionTitle,renderConnection,uiIcon,stateClass,statusText}){
function ensureSelection(){const r=state.selectedRule;if(!r)return;state.selection.setting=r.backendSetting||'';const st=state.settings.find(x=>x.id===r.backendSetting);if(st){if(st.allowValueOverride&&state.selection.value==null)state.selection.value=st.suggested;if(st.requiresInput&&state.selection.customValue==null)state.selection.customValue=st.inputDefault||'';state.selection.accountScope=st.domainPolicySensitive?'Domain':st.scope==='User'?'Users':'LocalComputers';}if(state.inventory){if(!state.inventory.gpos.some(g=>g.id===state.selection.gpoId&&g.selectable))state.selection.gpoId='';const scopes=st?.domainPolicySensitive?state.inventory.scopes.filter(x=>x.kind==='Domain'):state.inventory.scopes.filter(x=>x.kind==='OU');if(!scopes.some(x=>x.dn===state.selection.scopeDn))state.selection.scopeDn=st?.domainPolicySensitive?(scopes[0]?.dn||''):'';}}
function selectedGpo(){return state.inventory?.gpos.find(g=>g.id===state.selection.gpoId)||null;}
function stepper(active){const steps=[say('Qayda','Control'),say('Hədəf','Target'),say('Plan','Preview'),say('Təsdiq','Approval'),say('Tətbiq','Apply'),say('Yoxlama','Verify')];return `<div class="stepper">${steps.map((s,idx)=>`<div aria-current="${idx+1===active?'step':'false'}" class="step ${stepConfirmed(idx)?'done':idx+1===active?'active':''}"><b>${stepConfirmed(idx)?'✓':idx+1}</b><span>${s}</span></div>`).join('')}</div>`;}
function stepConfirmed(index){const r=state.selectedRule,h=r?relevantHistory(r)[0]:null,result=h?.result||{};return [!!r,!!state.selection.gpoId,!!state.plan||!!h?.plan,!!state.approval.reviewed||!!h?.approval,result.gpoPublished===true,!!h&&GpoUiDomain.classify(h).compliant][index];}
function currentStep(){const run=state.selectedRule?relevantHistory(state.selectedRule)[0]:null;const step=GpoUiDomain.workflowStep({plan:state.plan,approvalReviewed:state.approval.reviewed,run});return !run&&!state.plan&&state.selection.gpoId?2:step;}
function controlHeader(r){const d=topDomainForRule(r),risk=riskFor(r);return `${window.GpoComponents.breadcrumb(state,r)}${window.GpoStudioUI.remediation(state)}<div class="control-header"><button class="back-link" data-back>← ${tr('back')}</button><div class="control-title-row"><div class="control-id-block"><span>${esc(r.id)}</span><small>${esc(d?.title||'CIS Control')}</small></div><div class="control-title"><div class="control-badges">${badges(r)}<span class="risk-pill ${risk.cls}">${risk.name} ${tr('risk')}</span></div><h1>${esc(r.title)}</h1></div><button class="favorite-action ${state.favorites.has(r.id)?'active':''}" data-favorite="${esc(r.id)}">${state.favorites.has(r.id)?'★ Saved':'☆ Save'}</button></div>${window.GpoRemediationGuides?.get(r.id)?`<p class="guide-boundary">${say('Guided remediation · avtomatik tətbiq bağlıdır','Guided remediation · automatic execution blocked')}</p>`:stepper(currentStep())}<div class="control-tabs" role="tablist" aria-label="${say('Nəzarət detalları','Control details')}">${[['overview',tr('overview')],['remediation',say('Hədəf və tətbiq','Target & apply')],['verification',tr('verification')]].map(([k,l])=>`<button role="tab" aria-selected="${state.tab===k?'true':'false'}" data-tab="${k}" class="${state.tab===k?'active':''}">${l}</button>`).join('')}<details class="ux-more-tabs" ${state.tab==='impact'||state.tab==='audit'?'open':''}><summary>${say('Ətraflı','More')} ⌄</summary><div><button type="button" data-tab="impact" class="${state.tab==='impact'?'active':''}">${tr('impact')}</button><button type="button" data-tab="audit" class="${state.tab==='audit'?'active':''}">${tr('audit')}</button></div></details></div></div>`;}
function overviewTab(r){
  if(window.GpoRemediationGuides?.get(r.id))return window.GpoRemediationGuides.render(r.id,{state,esc,say});
  const risk=riskFor(r),mapping=state.settings.find(x=>x.id===r.backendSetting);
  const kind=mapping?.domainPolicySensitive?'Domain':String(mapping?.scope||'Computer');
  const scope=kind==='User'?say('User OU','User OU'):kind==='Domain'?say('Domen kökü','Domain root'):say('Computer OU','Computer OU');
  const processing=kind==='User'?'User Configuration':'Computer Configuration';
  const isRight=String(r.id).startsWith('2.2.');
  return `<div class="ux-overview-layout">
    <section class="ux-overview-main"><span class="eyebrow">CIS ${esc(r.id)} · ${esc(r.level)}</span><h2>${say('Bu nəzarət nəyi dəyişir?','What does this control change?')}</h2><p>${esc(r.description||say('Təsvir təqdim edilməyib.','No benchmark description available.'))}</p><div class="ux-overview-cta"><button type="button" class="primary-action" data-control-start ${r.implementation==='live'?'':'disabled'}>${say('GPO və OU seçərək başla','Choose GPO & OU')} →</button><span>${say('Əvvəlcə read-only Preview yaradılır','Starts with a read-only preview')}</span></div></section>
    <aside class="ux-overview-side"><div class="ux-overview-fact"><small>${say('Tövsiyə olunan dəyər','Recommended value')}</small><strong>${esc(r.recommended||say('Benchmark-ə bax','Refer to benchmark'))}</strong></div><div class="ux-overview-fact"><small>${say('GPO konfiqurasiyası','GPO processing')}</small><strong>${processing}</strong><span>${scope}</span></div><div class="ux-overview-fact"><small>${say('Əməliyyat riski','Operational impact')}</small><strong>${esc(risk.name)}</strong><span>${esc(risk.copy)}</span></div></aside>
    ${isRight?`<p class="ux-policy-hint">${say('Bu control istifadəçi və qrup hüquqlarını dəyişsə də, kompüter üzərindən tətbiq edilir. User OU deyil, kompüter OU-su seçilməlidir.','Although this control assigns rights to accounts or groups, it is processed by Computer Configuration. Choose the computer OU.')}</p>`:''}
    <details class="ux-advanced-block ux-overview-more"><summary><span>${say('Texniki detalları və təhlükəsizlik qeydlərini göstər','Show technical details and safety notes')}</span><span aria-hidden="true">⌄</span></summary><div class="ux-overview-technical"><div class="ux-meta-tags"><span>${esc(r.level)}</span><span>${esc(r.automation)}</span><span>${esc(sectionTitle(r.sectionId))}</span><span>CIS v4.0.0</span></div><p>${say('Yazmadan əvvəl GPO linkləri, inherited GPO-lar, security filtering, WMI və mümkün server-rol istisnaları Preview-də yoxlanılmalıdır.','Review GPO links, inheritance, security filters, WMI and server-role exceptions in Preview before writing.')}</p>${mapping?.warnings?.length?`<ul>${mapping.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}</div></details>
  </div>`;
}

function relevantHistory(rule){return state.history.filter(h=>h.plan?.selection?.setting===(rule.backendSetting||rule.id)).sort((a,b)=>Date.parse(b.updatedAt||0)-Date.parse(a.updatedAt||0));}
function gpoPicker(){const i=state.inventory;if(!i)return'';const selected=selectedGpo();const q=state.gpoSearch.trim().toLowerCase();const all=i.gpos||[];const items=all.filter(g=>!q||g.name.toLowerCase().includes(q)||String(g.id||'').toLowerCase().includes(q)).slice(0,80);const trigger=`<button type="button" class="gpo-picker-trigger" data-gpo-toggle><span><small>${say('SEÇİLMİŞ GPO','SELECTED GPO')}</small><strong>${selected?esc(selected.name):say('GPO seçin','Choose a Group Policy Object')}</strong>${selected?`<em>${esc(selected.id||'')}</em>`:''}</span><b>⌄</b></button>`;if(!state.gpoPickerOpen)return `<div class="gpo-picker">${trigger}${selected?`<div class="pr-identities">${window.GpoPremium.copyValue(state,selected.id,'GPO GUID')}</div>`:''}</div>`;return `<div class="gpo-picker">${trigger}<div class="gpo-modal-backdrop" data-gpo-close></div><section class="gpo-modal" role="dialog" aria-modal="true" aria-label="${say('GPO seçimi','GPO selection')}"><header class="gpo-modal-head"><div><small>${say('GROUP POLICY OBJECT','GROUP POLICY OBJECT')}</small><h2>${say('Tətbiq ediləcək GPO-nu seçin','Choose the GPO to change')}</h2><p>${say('Yalnız real domen inventarından gələn obyektlər göstərilir. Qorunan siyasətlər ayrıca işarələnir.','Only objects discovered from the live domain inventory are shown. Protected policies are marked explicitly.')}</p></div><button type="button" class="gpo-modal-close" data-gpo-close aria-label="${say('Bağla','Close')}">×</button></header><div class="gpo-modal-search"><span>⌕</span><input id="gpo-search" value="${esc(state.gpoSearch)}" aria-label="${say('GPO adı və ya GUID','GPO name or GUID')}" placeholder="${say('GPO adı və ya GUID ilə axtarın…','Search by GPO name or GUID…')}" autofocus><b>${items.length}/${all.length}</b></div><div class="gpo-modal-results">${items.map(g=>`<button type="button" class="gpo-option ${g.id===state.selection.gpoId?'selected':''}" data-gpo="${esc(g.id)}" aria-pressed="${g.id===state.selection.gpoId}" ${g.selectable?'':'disabled'}><span class="gpo-option-icon">${g.id===state.selection.gpoId?'✓':'G'}</span><span class="gpo-option-copy"><strong>${esc(g.name)}</strong><small>${esc(g.id||'')}</small></span><span class="gpo-option-badges">${g.protected?`<i class="protected">${say('Qorunan','Protected')}</i>`:''}<i class="${g.selectable?'ready':'blocked'}">${g.selectable?say('Seçilə bilər','Selectable'):say('Bu workflow üçün bağlıdır','Unavailable')}</i></span></button>`).join('')||`<div class="gpo-modal-empty">${window.GpoPremium.emptyIcon()}<strong>${say('Uyğun GPO tapılmadı','No matching GPO')}</strong><span>${say('Axtarış sözünü dəyişin.','Try a different search term.')}</span></div>`}</div><footer class="gpo-modal-foot"><span>${say('Seçim yalnız preview planı yaradır; bu mərhələdə domenə yazı edilmir.','Selection only prepares a preview plan; no domain write occurs at this stage.')}</span><button type="button" data-gpo-close>${say('Bağla','Close')}</button></footer></section></div>`;}

function targetForm(r){
 const i=state.inventory,s=state.selection,st=state.settings.find(x=>x.id===r.backendSetting);
 if(!i)return `${window.GpoProduct.disconnectedControl(state,r)}<div class="locked-state">${renderConnection()}<h3>${say('Real GPO və tətbiq sahəsini seçmək üçün giriş ekranını açın.','Open the sign-in screen to select a real GPO and scope.')}</h3></div>`;
 const user=String(st?.scope||'Computer').toLowerCase()==='user';const userRight=String(st?.category||r.sectionId||'').startsWith('2.2')||String(r.id||'').startsWith('2.2.');
 const desired=st?.requiresInput?`<label>${esc(st.inputLabel||say('Tələb olunan dəyər','Required value'))}<input name="customValue" value="${esc(s.customValue||st.inputDefault||'')}" maxlength="4096" required></label>`:st?.allowValueOverride?`<label>${say('Tətbiq ediləcək dəyər','Desired value')}<input type="number" name="value" min="${st.minimum??0}" max="${st.maximum??99999}" value="${s.value}"></label>`:`<label>${say('Tətbiq ediləcək dəyər','Desired benchmark state')}<input disabled value="${esc(st?.recommended||'Fixed production mapping')}"></label>`;
 const userTargets=user?`<div class="target-scope-note"><span>U</span><div><strong>${say('User Configuration','User Configuration')}</strong><small>${say('GPO aşağıdakı user OU-ya linklənir. Endpoint OU yalnız user gpupdate və canlı HKCU yoxlaması üçündür.','The GPO links to the user OU below. The endpoint OU is only for user gpupdate and live HKCU verification.')}</small></div></div><div class="scope-target-label"><span>${say('User OU — siyasətin tətbiq sahəsi','User OU — policy scope')}</span>${window.GpoScopePicker.field(i.scopes,s.scopeDn,'scopeDn','OU',state.lang)}<small>${say('Preview bu OU-dakı aktiv istifadəçilərin sayını və nümunəsini göstərəcək.','Preview will show the active user count and a sample from this OU.')}</small></div><div class="scope-target-label"><span>${say('Endpoint OU — istifadəçi sessiyalarının kompüterləri','Endpoint OU — computers hosting user sessions')}</span>${window.GpoScopePicker.field(i.scopes,s.endpointScopeDn,'endpointScopeDn','OU',state.lang)}<small>${say('Yalnız ani user gpupdate seçəndə tələb olunur; user OU ilə eyni olmaq məcburiyyətində deyil.','Required only for immediate user gpupdate; it does not have to match the user OU.')}</small></div><label>${say('Yoxlama istifadəçisi','Verification user')}<input name="verificationUser" value="${esc(s.verificationUser||'')}" maxlength="256" placeholder="DOMAIN\\user və ya user@domain"><small>${say('Seçilmiş user OU daxilində aktiv hesab olmalıdır. HKCU yalnız profil endpoint-də yüklüdürsə yoxlanır.','Must be an enabled account in the selected user OU. HKCU can be verified only when its profile is loaded on the endpoint.')}</small></label>`:`<div class="target-scope-note"><span>PC</span><div><strong>${say('Computer Configuration','Computer Configuration')}</strong><small>${userRight?say('User Rights Assignment kompüter siyasətidir: istifadəçi/qruplar imtiyaz alır, amma GPO kompüter OU-suna linklənir.','User Rights Assignment is COMPUTER policy: accounts/groups receive rights, but the GPO links to the COMPUTER OU.'):say('GPO seçilən kompüter OU/domen sahəsinə linklənir.','The GPO links to the selected computer OU/domain scope.')}</small></div></div><div class="scope-target-label"><span>${say('Kompüter tətbiq sahəsi (OU / domen)','Computer apply scope (OU / domain)')}</span>${window.GpoScopePicker.field(i.scopes,s.scopeDn,'scopeDn',st?.domainPolicySensitive?'Domain':'OU',state.lang)}</div>`;
 const refresh=`<fieldset class="refresh-strategy"><legend>${say('Yenilənmə strategiyası','Post-apply refresh strategy')}</legend><label class="refresh-choice ${s.refresh==='None'?'selected':''}"><input type="radio" name="refresh" value="None" ${s.refresh==='None'?'checked':''}><span class="refresh-choice-icon">○</span><span><b>${say('Normal dövrü gözlə','Wait for normal cycle')}</b><small>${say(user?'İstifadəçi növbəti policy cycle/logon zamanı yenilənir.':'Əlavə gpupdate işə salınmır.','Policy updates on the next normal cycle/logon.')}</small></span></label>${!st?.domainPolicySensitive?'':`<label class="refresh-choice ${s.refresh==='Pdc'?'selected':''}"><input type="radio" name="refresh" value="Pdc" ${s.refresh==='Pdc'?'checked':''}><span class="refresh-choice-icon">DC</span><span><b>${say('PDC-ni yenilə','Refresh PDC')}</b><small>${say('PDC-də computer policy refresh planlaşdırılır.','Schedules computer policy refresh on the PDC.')}</small></span></label>`}<label class="refresh-choice ${s.refresh==='Scope'?'selected':''}"><input type="radio" name="refresh" value="Scope" ${s.refresh==='Scope'?'checked':''}><span class="refresh-choice-icon">${user?'U':'PC'}</span><span><b>${say(user?'Endpoint OU-da user policy-ni yenilə':'Scope kompüterlərini yenilə',user?'Refresh user policy on endpoint OU':'Refresh scope computers')}</b><small>${say(user?'Seçilmiş endpoint OU-dakı icazəli kompüterlərdə /target:user /force planlaşdırılır.':'Hədəf kompüterlərdə /target:computer /force planlaşdırılır.',user?'Schedules /target:user /force on allowed computers in the endpoint OU.':'Schedules /target:computer /force on target computers.')}</small></span></label></fieldset>`;
 return `<form id="gpo-selection" class="target-form"><div class="form-section-title"><span>01</span><div><small>${say('HƏDƏF','TARGET')}</small><h2>${say('Siyasətin obyektini və icra endpoint-ini seçin','Choose policy objects and execution endpoints')}</h2></div></div>${gpoPicker()}<div class="form-grid">${userTargets}${r.implementation==='live'?desired:''}${refresh}</div><label class="switch-row"><input type="checkbox" name="firstLink" ${s.firstLink?'checked':''}><span><b>${say('Ən yüksək link prioriteti','Highest link priority')}</b><small>${say('Mövcud filtering və Enforced sazlamaları dəyişmir.','Existing filtering and Enforced settings are preserved.')}</small></span></label><button class="primary-action" ${r.implementation==='live'&&s.gpoId&&s.scopeDn?'':'disabled'}>${tr('preview')} <span>→</span></button>${window.GpoScopePicker.modal(i.scopes,state.scopeModal,state.scopeQuery,state.scopeExpanded,s,state.lang,!!st?.domainPolicySensitive)}</form>`;
}
function impactTab(r){if(window.GpoRemediationGuides?.get(r.id))return window.GpoRemediationGuides.render(r.id,{state,esc,say});const risk=riskFor(r),g=selectedGpo(),scope=state.inventory?.scopes.find(x=>x.dn===state.selection.scopeDn),live=state.plan?.preview?.impact,conflicts=live?.conflicts||[],ao=live?.affectedObjects;const graphNodes=[['Domain root',state.inventory?.domain||'Not connected'],['Selected GPO',g?.name||'Not selected'],['Target scope',scope?.name||'Not selected'],['Effective policy',state.plan?'Verification after Apply':'Preview required']];const sample=ao?.users?(ao.sampleUsers||[]):ao?.sampleHosts||[];return `<div class="impact-layout"><section class="impact-hero ${risk.cls}"><span>${say('TƏXMİNİ ƏMƏLİYYAT TƏSİRİ','ESTIMATED OPERATIONAL IMPACT')}</span><h2>${risk.name}</h2><p>${esc(risk.copy)} ${say('Bu server mapping metadata-sına əsaslanan əməliyyat istiqamətidir; yekun risk qərarı deyil.','This is operational guidance from server mapping metadata, not a final risk decision.')}</p></section><div class="impact-grid"><section class="content-card"><span class="card-kicker">SELECTED GPO</span><h2>${g?esc(g.name):'Not selected'}</h2><div class="fact-list"><span><b>Protected</b>${g?.protected?'Yes':'No'}</span><span><b>Selectable</b>${g?.selectable?'Yes':'No'}</span></div></section><section class="content-card"><span class="card-kicker">TARGET SCOPE</span><h2>${scope?esc(scope.name):'Not selected'}</h2><p>${scope?esc(scope.dn):'Choose a domain/OU target in Remediation.'}</p></section><section class="content-card span2 conflict-card"><div class="card-title-row"><div><span class="card-kicker">POLICY CONFLICT GRAPH</span><h2>Inheritance & precedence path</h2></div><span class="probe-badge">${live?'LIVE ANALYSIS':'PREVIEW REQUIRED'}</span></div><div class="policy-graph">${graphNodes.map((n,i)=>`<button type="button" class="graph-node ${i===state.impactNode?'focus':''}" data-impact-node="${i}" aria-pressed="${i===state.impactNode}"><span>${i+1}</span><div><small>${esc(n[0])}</small><strong>${esc(n[1])}</strong></div></button>${i<graphNodes.length-1?'<i>↓</i>':''}`).join('')}</div><div class="graph-detail"><strong>${esc(graphNodes[state.impactNode]?.[0]||'')}</strong><p>${esc([state.inventory?.domain||say('Qoşulmayıb','Not connected'),g?.id||say('GPO seçilməyib','No GPO selected'),scope?.dn||say('Hədəf seçilməyib','No target selected'),say('Faktiki siyasət ayrıca canlı yoxlama ilə təsdiqlənir.','Effective policy requires independent live verification.')][state.impactNode])}</p></div>${live?`<div class="warning-list">${conflicts.length?conflicts.map(c=>`<div><b>${esc(c.severity||'!')}</b><span>${esc(c.message)}</span></div>`).join(''):'<div><b>✓</b><span>No conflict was detected by the current bounded analysis; this is not a full RSoP guarantee.</span></div>'}</div><p class="engine-note">Inheritance: ${esc(live.inheritance)} · WMI filter: ${esc(live.wmiFilter||'none')} · Security filtering: ${esc((live.securityFiltering||[]).join(', ')||'none detected')}</p>`:'<p class="engine-note">Generate a read-only plan to run live inheritance, precedence, security filtering and WMI analysis.</p>'}</section><section class="content-card span2 affected-card"><div class="card-title-row"><div><span class="card-kicker">PRE-FILTER SCOPE INVENTORY</span><h2>${ao?.users?say('Seçilmiş user OU','Selected user OU'):say('Seçilmiş kompüter sahəsi','Selected computer scope')}</h2></div><span class="probe-badge">${ao?'LIVE INVENTORY':'PREVIEW REQUIRED'}</span></div><div class="object-stats"><div><strong>${ao?.users??'—'}</strong><span>Users</span></div><div><strong>${ao?.computers??'—'}</strong><span>Computers</span></div><div><strong>${ao?.servers??'—'}</strong><span>Servers</span></div><div><strong>${ao?.workstations??'—'}</strong><span>Workstations</span></div></div>${ao?`<div class="object-placeholder"><span>⌁</span><p>${say('Saylar security/WMI filtering və RSoP nəticəsi deyil.','Counts are before security/WMI filtering and RSoP evaluation.')} ${ao.truncated?'Inventory capped at 5,000 objects. ':''}${say('Nümunə','Sample')}: ${esc(sample.slice(0,8).join(', ')||say('Obyekt tapılmadı.','No objects returned.'))}</p></div>`:'<div class="object-placeholder"><span>⌁</span><p>Generate a plan to load the directory scope inventory.</p></div>'}</section></div></div>`;}
function smartTargetPreview(p){const a=p?.preview?.impact?.affectedObjects;if(!a)return '';const kind=a.targetKind||((p.selection?.accountScope==='Users')?'User':'Computer');const domain=kind==='DomainAccount';const total=domain?'—':kind==='User'?a.users??0:a.computers??0;const subtitle=domain?say('Domen hesab siyasəti — ayrıca OU client siyahısı yoxdur.','Domain account policy — not a list of OU client computers.'):kind==='User'?say('Aktiv istifadəçilər, seçilmiş OU və alt OU-lar.','Enabled users in the selected OU and descendants.'):say('Aktiv kompüterlər, seçilmiş OU və alt OU-lar.','Enabled computers in the selected OU and descendants.');const filtering=(p.preview?.impact?.securityFiltering||[]);return `<section class="content-card target-assurance"><span class="card-kicker">${say('CANLI TARGET ANALİZİ','LIVE TARGET ANALYSIS')}</span><h3>${say('Hədəfləmə nəticəsi','Targeting preview')} · ${esc(kind)}</h3><div class="assurance-grid"><div><small>${say('OBYEKTLƏR','OBJECTS')}</small><strong>${esc(total)}</strong></div><div><small>${say('MƏHDUDİYYƏT','SECURITY FILTER')}</small><strong>${esc(filtering.length)}</strong></div><div><small>WMI</small><strong>${p.preview.impact.wmiFilter?'Filter':'—'}</strong></div><div><small>${say('KONFLİKT','CONFLICTS')}</small><strong>${(p.preview.impact.conflicts||[]).length}</strong></div></div><p>${esc(subtitle)} ${say('Bu saylar GPO tətbiqinin sübutu deyil; security filtering/WMI və loopback nəticəni dəyişə bilər.','Counts are not proof of policy application; security filtering/WMI and loopback may change the result.')}</p>${a.truncated?`<p role="alert" class="wf-warning">${say('Inventar tam deyil.','Inventory is incomplete.')}</p>`:''}</section>`;}
function planBlock(r){const p=state.plan;if(!p)return `<div class="preview-empty dryrun-empty"><span>DRY RUN / WHAT-IF</span><h3>No read-only plan generated yet.</h3><p>Select a GPO and target, then generate a plan. The preview performs no domain write.</p><div class="dryrun-features"><span>Before/after diff</span><span>Link intent</span><span>Warning aggregation</span><span>Rollback context</span></div></div>`;const before=p.preview.previousValue??'Not configured',after=p.preview.desiredValue??p.selection.customValue??p.selection.value;return `<section class="plan-card"><div class="plan-head"><div><span>DRY RUN · READ-ONLY PREVIEW</span><h2>Change plan ready</h2></div><span class="safe-badge">NO WRITE YET</span></div><div class="diff-card"><div class="diff-head"><span>BEFORE / AFTER DIFF</span><strong>${esc(r.id)}</strong></div><div class="diff-row"><div class="diff-before"><small>CURRENT</small><strong>${esc(before)}</strong></div><span class="diff-arrow">→</span><div class="diff-after"><small>DESIRED</small><strong>${esc(after)}</strong></div></div></div>${smartTargetPreview(p)}<div class="plan-facts"><div><span>GPO</span><strong>${esc(p.preview.gpo.name)}</strong></div><div><span>Target</span><strong>${window.GpoPremium.copyValue(state,p.preview.scope.dn,'DN')}</strong></div><div><span>Link</span><strong>${p.preview.existingLink?'Existing link':'New link'}${p.selection.firstLink?' · priority 1':''}</strong></div><div><span>Execution</span><strong>${esc(p.executionUser)}</strong></div><div><span>gpupdate</span><strong>${p.preview.refreshComputers?.length?`${p.preview.refreshComputers.length} target(s)`:'Not requested'}</strong></div><div><span>Rollback</span><strong>Backup before write</strong></div></div>${p.preview.warnings?.length?`<div class="warning-list">${p.preview.warnings.map((w,i)=>`<div><b>!</b><span>${esc(w)}</span></div>`).join('')}</div>`:''}<div class="approval-box"><div class="form-section-title"><span>04</span><div><small>GOVERNANCE</small><h2>${tr('approval')}</h2></div></div><div class="form-grid"><label>Change / Ticket ID<input id="approval-ref" value="${esc(state.approval.reference)}" placeholder="CHG-2026-001"></label><label>Operator-entered approver reference (optional)<input id="approval-by" value="${esc(state.approval.approver)}" placeholder="Reference only; not identity proof"></label></div><label class="switch-row"><input id="approval-ok" type="checkbox" ${state.approval.reviewed?'checked':''}><span><b>Impact reviewed and approved</b><small>I reviewed the target, GPO, scope and potential precedence impact.</small></span></label>${state.approval.reviewed&&state.service?.writesEnabled&&p.writeAuthorized?`<form id="gpo-apply" class="apply-box"><label class="switch-row"><input name="impact" type="checkbox" ${state.applyDraft.impact?'checked':''} required><span><b>Confirm production impact</b><small>Backup will be created before the GPO write.</small></span></label>${p.preview.gpo.protected?`<label class="switch-row danger"><input name="protected" type="checkbox" ${state.applyDraft.protected?'checked':''} required><span><b>Protected GPO confirmation</b><small>I explicitly approve changing this protected/default policy.</small></span></label>`:''}<label>Type APPLY to continue<input name="confirmation" required pattern="APPLY" autocomplete="off" value="${esc(state.applyDraft.confirmation)}" placeholder="APPLY"></label><button class="danger-action">Backup → Apply → Link → Verify</button></form>`:''}${(!state.service?.writesEnabled||!p.writeAuthorized)?(state.writeGateBlocked?`<div class="change-gate locked"><div class="change-gate-icon">!</div><div class="change-gate-copy"><small>${say('CHANGE GATE TRANSITION','CHANGE GATE TRANSITION')}</small><strong>${say('Avtomatik təkrar bloklanıb','Automatic retry blocked')}</strong><p>${say('Əvvəlki restart-dan sonra backend write gate-i aktiv görmədi. Loop yaratmamaq üçün plan saxlanılıb, amma gate yenidən avtomatik açılmayacaq. Settings və Local Control Center-də scope/config vəziyyətini yoxlayın.','After the previous restart the backend did not report the write gate as active. The plan is preserved, but automatic reactivation is blocked to prevent a loop. Inspect scope/config state in Settings and Local Control Center.')}</p></div><button type="button" class="primary-action gate-action" data-settings>${say('Sazlamaları yoxla','Review settings')}</button></div>`:`<div class="change-gate locked"><div class="change-gate-icon">⛨</div><div class="change-gate-copy"><small>${say('PRODUCTION CHANGE GATE','PRODUCTION CHANGE GATE')}</small><strong>${say('Dəyişiklik rejimi bağlıdır','Change mode is read-only')}</strong><p>${say('Bu düymə seçilmiş GPO + scope-u avtomatik production allowlist-ə kilidləyir, change gate-i açır və yalnız bir idarəli restart edir. GUID və OU-nu ayrıca Settings-də yazmaq lazım deyil.','This action automatically locks the selected GPO + scope into the production allowlist, enables the change gate, and performs only one managed restart. No manual GUID or OU entry is required in Settings.')}</p></div><button type="button" class="primary-action gate-action" data-enable-write>${say('Bu GPO + scope-u təsdiqlə və davam et','Authorize this GPO + scope & continue')}</button></div>`):`<div class="change-gate ready"><div class="change-gate-icon">✓</div><div class="change-gate-copy"><small>${say('PRODUCTION CHANGE GATE','PRODUCTION CHANGE GATE')}</small><strong>${say('Dəyişiklik rejimi aktivdir','Change mode enabled')}</strong><p>${say('Plan təsdiqdən sonra Backup → Apply → Link → Verify ardıcıllığı ilə icra ediləcək.','After approval, the plan will run through Backup → Apply → Link → Verify.')}</p></div></div>`}</div></section>`;}
function remediationTab(r){if(window.GpoRemediationGuides?.get(r.id))return window.GpoRemediationGuides.render(r.id,{state,esc,say});return `<div class="ux-workflow-caption"><div><span class="eyebrow">CONTROL WORKFLOW</span><strong>${say('GPO → OU → Preview','GPO → OU → Preview')}</strong></div><span>${say('Heç bir dəyişiklik təsdiqsiz icra olunmur','No write without explicit approval')}</span></div><div class="remediation-layout"><section class="content-card target-card">${targetForm(r)}</section><section>${planBlock(r)}</section></div>`;}
function verificationTimeline(h){if(!h)return `<div class="verification-empty"><div class="ux-empty-icon" aria-hidden="true">◌</div><h2>${say('Hələ yoxlama aparılmayıb','No verification performed yet')}</h2><p>After Apply, this workspace will show GPO write, link, gpupdate, replication and effective-policy status.</p></div>`;const rr=h.result.refreshResults||[],v=h.result.verification,ec=h.result.endpointChecks||[];const refreshOk=rr.length&&rr.every(x=>['OK','SUCCESS'].includes(String(x.state).toUpperCase()));const effective=String(h.result.effectiveStatus||'ENDPOINT_VERIFICATION_PENDING');const effBad=/MISMATCH|FAILED/.test(effective),effOk=/VERIFIED|MATCHES/.test(effective)&&!/PENDING/.test(effective);const stages=[['GPO write',h.result.gpoPublished?'Verified':'Not confirmed',h.result.gpoPublished?'ok':'bad'],['Link verification',h.result.linkVerified?'Verified':'Not confirmed',h.result.linkVerified?'ok':'bad'],['gpupdate',rr.length?rr.map(x=>`${x.computer}: ${x.state}`).join(' · '):'Not requested',rr.some(x=>x.state==='FAILED')?'bad':refreshOk?'ok':'pending'],['AD / SYSVOL replication',v?(v.replicationConverged?'Converged across checked DCs':(v.replicationWarnings||[]).join(' · ')||'Pending'):'Not checked',v?(v.replicationConverged?'ok':'pending'):'pending'],['Effective policy',effective+(ec.length?` · ${ec.map(x=>`${x.hostname}: ${x.state}`).join(' · ')}`:''),effBad?'bad':effOk?'ok':'pending']];return `<div class="verify-timeline">${stages.map((st,i)=>`<div class="verify-node ${st[2]}"><span>${st[2]==='ok'?'✓':st[2]==='bad'?'!':i+1}</span><div><small>STAGE ${i+1}</small><h3>${st[0]}</h3><p>${esc(st[1])}</p></div></div>`).join('')}</div>`;}
function resultSummary(h){if(!h)return'';const r=h.result||{},quality=GpoUiDomain.classify(h),rr=r.refreshResults||[],before=h.plan?.preview?.previousValue??'Not configured',desired=h.plan?.preview?.desiredValue??'—',drift=quality.attention,verified=quality.compliant,endpoint=(r.endpointChecks||[])[0],actual=r.currentValue??'—',rep=r.verification?.replicationConverged,scheduled=rr.filter(x=>x.state==='SCHEDULED').length,failed=rr.filter(x=>x.state==='FAILED').length;return `<section class="result-summary ${drift?'danger':verified?'success':'pending'}"><div class="result-summary-head"><div><span class="card-kicker">LIVE CHANGE RESULT</span><h2>${esc(statusText(r.effectiveStatus==='ENDPOINT_MISMATCH'?r.effectiveStatus:r.state))}</h2><p>${esc(r.message||'')}</p></div><span class="result-state ${stateClass(r.state)}">${esc(statusText(r.state))}</span></div><div class="result-diff"><div><small>BEFORE</small><strong>${esc(before)}</strong></div><span>→</span><div><small>REQUESTED</small><strong>${esc(desired)}</strong></div><span>→</span><div><small>LIVE GPO VALUE</small><strong>${esc(actual)}</strong></div></div><div class="assurance-grid"><div><small>GPO CONFIGURATION</small><strong class="${r.gpoPublished?'ok':'bad'}">${r.gpoPublished?'✓ MATCH':'! MISMATCH'}</strong></div><div><small>GPO LINK</small><strong class="${r.linkVerified?'ok':'bad'}">${r.linkVerified?'✓ ACTIVE':'! NOT VERIFIED'}</strong></div><div><small>AD / SYSVOL</small><strong class="${rep?'ok':'pending'}">${rep?'✓ CONVERGED':'· PENDING'}</strong></div><div><small>EFFECTIVE POLICY</small><strong class="${stateClass(r.effectiveStatus)}">${esc(statusText(r.effectiveStatus))}</strong></div></div>${r.effectiveStatus==='ENDPOINT_MISMATCH'&&r.gpoPublished&&r.linkVerified?`<p class="endpoint-guidance">${say('GPO dəyəri düzgündür. Endpoint-də fərqin səbəbini yoxlayın: gpupdate nəticəsi, üstün gələn başqa GPO, restart və ya yeni giriş tələbi. Hədəf kompüterdə gpresult /scope computer /r ilə tətbiq olunan siyasətləri yoxlayın.','The GPO value matches. Investigate endpoint refresh completion, a winning policy, or a restart/logon requirement. Run gpresult /scope computer /r on the target computer to inspect applied policies.')}</p>`:''}${(r.endpointChecks||[]).map(x=>`<div class="endpoint-evidence"><strong>${esc(x.hostname)} · ${esc(statusText(x.state))}</strong><p>${esc(x.message||'')}</p><small>${say('Endpoint-də oxunan dəyər','Observed endpoint value')}</small><pre>${esc(x.actualValue??say('Oxuna bilmədi','Unavailable'))}</pre></div>`).join('')}${rr.length?`<div class="refresh-summary"><span>gpupdate targets <b>${rr.length}</b></span><span>Scheduled <b>${scheduled}</b></span><span>Failed <b>${failed}</b></span></div>`:''}<div class="result-actions"><button data-verify="${esc(h.id)}" title="Reads live GPO, link, replication metadata and endpoint evidence again">↻ ${say('Canlı vəziyyəti yenidən yoxla','Re-verify live state')}</button>${h.plan?.selection?.refresh&&(r.gpoPublished&&r.linkVerified||r.state==='ROLLED_BACK')?`<button class="primary-action compact" data-gpupdate="${esc(h.id)}" title="Schedules gpupdate /force on selected targets">${say('gpupdate /force işə sal','Run gpupdate /force')}</button>`:''}${drift&&(!r.gpoPublished||!r.linkVerified)?`<button class="primary-action compact danger-action" data-replan="${esc(h.id)}">${say('Yenidən remediation planı hazırla','Remediate again')}</button>`:''}<small>${say('Published, replication və endpoint-effective statusları ayrıca göstərilir. gpupdate yalnız operator seçimi ilə işləyir.','Publication, replication and endpoint-effective status are tracked separately. gpupdate only runs by explicit operator action.')}</small></div></section>`;}
const renderResultSummary=resultSummary;
resultSummary=function(h){
 if(h?.plan?.selection?.refresh==='None'&&h?.result?.state!=='ROLLED_BACK')h={...h,plan:{...h.plan,selection:{...h.plan.selection,refresh:''}}};
 let html=renderResultSummary(h),index=0;
 html=html.replace(/(<div class="endpoint-evidence">[\s\S]*?<pre>[\s\S]*?<\/pre>)(<\/div>)/g,(match,content,close)=>{const endpoint=(h?.result?.endpointChecks||[])[index++];if(!endpoint)return match;const command=window.GpoComponents.manualCheck(state,h,endpoint);return `${content}<div class="manual-check-head"><small>${say('Manual yoxlama üçün PowerShell (endpoint-də Administrator kimi)','PowerShell manual check (run as Administrator on the endpoint)')}</small><button type="button" data-copy-value="${esc(command)}">${say('Kopyala','Copy')}</button></div><pre class="manual-check-command">${esc(command)}</pre>${close}`;});
 if(/^(APPLYING|ROLLBACKING|VERIFYING|REFRESHING)$/.test(h?.result?.state||''))html=html.replace(/<button[^>]*data-gpupdate[^>]*>[\s\S]*?<\/button>/,'');
 if(h?.result?.state==='ROLLED_BACK')html=html.replace(/>gpupdate \/force işə sal</,`>${say('Rollback-dan sonra gpupdate /force','Run gpupdate /force after rollback')}<`);
 const stages=h?.result?.verificationStages||[],diagnosis=h?.result?.diagnosis||[];
 if(stages.length)html=html.replace('<div class="result-actions">',`<div class="assurance-stage-list">${stages.map(x=>`<div><strong>${esc(x.stage)} · ${esc(x.status)}</strong><p>${esc(x.evidence)}</p></div>`).join('')}</div>${diagnosis.length?`<details><summary>${say('Yoxlama üçün diaqnostik addımlar','Diagnostic checks')}</summary><ul>${diagnosis.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}<div class="result-actions">`);
 return html;
};
function verificationTab(r){if(window.GpoRemediationGuides?.get(r.id))return window.GpoRemediationGuides.render(r.id,{state,esc,say});const h=relevantHistory(r)[0];return `<div class="verify-page"><div class="section-intro"><span>POST-CHANGE ASSURANCE</span><h2>Verification pipeline</h2><p>Every status below is calculated from the live GPO/link state. A previous successful run is not treated as current truth.</p></div>${resultSummary(h)}${verificationTimeline(h)}<section class="content-card evidence-card"><div class="card-title-row"><div><span class="card-kicker">EVIDENCE PACK</span><h2>Change evidence & audit bundle</h2></div><button data-evidence ${h?'':'disabled'}>Prepare JSON evidence</button></div><div class="evidence-grid"><span>Before value</span><span>Requested value</span><span>GPO & target</span><span>Operator</span><span>Backup ID</span><span>Verification</span></div><p>${h?'Evidence is generated from the latest recorded operation for this control.':'Apply and record an operation before generating evidence.'}</p></section></div>`;}
function auditTab(r){const hs=relevantHistory(r);return `<div class="audit-page"><div class="section-intro"><span>CONTROL AUDIT TRAIL</span><h2>${esc(r.id)} ${say('əməliyyat tarixçəsi','operation history')}</h2><p>Operator, target, backup and recovery context for this control.</p></div>${hs.length?`<div class="audit-table"><div class="audit-head"><span>Operation</span><span>GPO</span><span>State</span><span>Backup</span><span>Action</span></div>${hs.map(h=>`<div class="audit-row"><span><b>${esc(h.id)}</b><small>${esc(h.plan?.executionUser||'—')}</small></span><span>${esc(h.plan?.preview?.gpo?.name||'—')}</span><span><i class="state-dot ${String(h.result?.state||'').toLowerCase()}"></i>${esc(h.result?.state||'UNKNOWN')}</span><span>${esc(h.result?.backupId||'—')}</span><span><button data-verify="${esc(h.id)}">Re-verify</button></span></div>`).join('')}</div>`:`<div class="panel-empty">No operation has been recorded for this control.</div>`}</div>`;}
function controlView(){const r=state.selectedRule;if(!r)return `<div class="missing-control"><h1>${tr('noSelection')}</h1><a href="#/benchmark">${tr('back')}</a></div>`;ensureSelection();let body=state.tab==='overview'?overviewTab(r):state.tab==='remediation'?remediationTab(r):state.tab==='impact'?impactTab(r):state.tab==='verification'?verificationTab(r):auditTab(r);return `${controlHeader(r)}<div class="control-body">${body}</div>`;}

return {ensureSelection,selectedGpo,targetForm,controlView,relevantHistory};}});})();
